const body = $json.body ?? $json;
const periodStart = String(body.periodStart ?? '').trim();
const periodEnd = String(body.periodEnd ?? '').trim();
const source = String(body.source ?? body.leadSource ?? '').trim();
const marketingChannel = String(body.marketingChannel ?? body.channel ?? '').trim();
const campaign = String(body.campaign ?? body.campaignName ?? '').trim();
if (!periodStart || !periodEnd) throw new Error('periodStart and periodEnd are required');
if (new Date(periodStart).getTime() > new Date(periodEnd).getTime()) throw new Error('periodStart must be before periodEnd');
return [{ json: { periodStart, periodEnd, source, marketingChannel, campaign, requestedAt: new Date().toISOString() } }];

const ctx = $json.data ?? $json;
const records = Array.isArray(ctx.records) ? ctx.records : (Array.isArray(ctx.campaigns) ? ctx.campaigns : []);
const valid = records.filter(r => r && (r.source || r.leadSource || r.marketingChannel || r.channel || r.campaign));
if (!valid.length) throw new Error('No valid marketing attribution data available for the requested period');
return [{ json: { records: valid, periodStart: $('Normalize Marketing ROI Request').first().json.periodStart, periodEnd: $('Normalize Marketing ROI Request').first().json.periodEnd } }];

const records = $json.records;
const buckets = new Map();
const num = v => Number.isFinite(Number(v)) ? Number(v) : 0;
for (const r of records) {
  const source = String(r.source ?? r.leadSource ?? 'unknown');
  const channel = String(r.marketingChannel ?? r.channel ?? 'unknown');
  const campaign = String(r.campaign ?? r.campaignName ?? 'unknown');
  const key = [source, channel, campaign].join('|');
  if (!buckets.has(key)) buckets.set(key, { source, marketingChannel: channel, campaign, leads: 0, qualifiedLeads: 0, appointments: 0, contracts: 0, closedDeals: 0, grossRevenue: 0, netProfit: 0, spend: 0 });
  const b = buckets.get(key);
  b.leads += num(r.leads ?? r.leadCount ?? (r.isLead ? 1 : 0));
  b.qualifiedLeads += num(r.qualifiedLeads ?? r.qualifiedLeadCount);
  b.appointments += num(r.appointments ?? r.appointmentCount);
  b.contracts += num(r.contracts ?? r.contractCount ?? (r.contractSigned ? 1 : 0));
  b.closedDeals += num(r.closedDeals ?? r.closedDealCount ?? (r.closed ? 1 : 0));
  b.grossRevenue += num(r.grossRevenue);
  b.netProfit += num(r.netProfit);
  b.spend += num(r.spend ?? r.sourceSpend ?? r.campaignSpend);
}
const rows = [...buckets.values()].map(b => ({ ...b, costPerLead: b.leads ? b.spend / b.leads : 0, costPerQualifiedLead: b.qualifiedLeads ? b.spend / b.qualifiedLeads : 0, costPerAppointment: b.appointments ? b.spend / b.appointments : 0, costPerContract: b.contracts ? b.spend / b.contracts : 0, costPerClosedDeal: b.closedDeals ? b.spend / b.closedDeals : 0, leadToQualifiedRate: b.leads ? b.qualifiedLeads / b.leads : 0, qualifiedToAppointmentRate: b.qualifiedLeads ? b.appointments / b.qualifiedLeads : 0, appointmentToContractRate: b.appointments ? b.contracts / b.appointments : 0, contractToCloseRate: b.contracts ? b.closedDeals / b.contracts : 0, leadToCloseRate: b.leads ? b.closedDeals / b.leads : 0, roi: b.spend ? (b.netProfit - b.spend) / b.spend : null, profitMultiple: b.spend ? b.netProfit / b.spend : null }));
const ranked = [...rows].sort((a,b) => ((b.roi ?? -Infinity) - (a.roi ?? -Infinity)) || (b.netProfit - a.netProfit));
const recommendations = ranked.map((r, i) => ({ rank: i + 1, source: r.source, marketingChannel: r.marketingChannel, campaign: r.campaign, action: r.roi === null ? 'collect_spend_data' : r.roi >= 2 ? 'scale' : r.roi >= 0.5 ? 'maintain_optimize' : r.roi >= 0 ? 'optimize_cautiously' : 'reduce_or_pause', reason: r.roi === null ? 'Spend is missing or zero' : 'ROI and downstream conversion performance' }));
const totals = rows.reduce((a,b) => { for (const k of ['leads','qualifiedLeads','appointments','contracts','closedDeals','grossRevenue','netProfit','spend']) a[k] += b[k]; return a; }, {leads:0,qualifiedLeads:0,appointments:0,contracts:0,closedDeals:0,grossRevenue:0,netProfit:0,spend:0});
totals.roi = totals.spend ? (totals.netProfit - totals.spend) / totals.spend : null;
totals.profitMultiple = totals.spend ? totals.netProfit / totals.spend : null;
totals.leadToCloseRate = totals.leads ? totals.closedDeals / totals.leads : 0;
return [{ json: { periodStart: $json.periodStart, periodEnd: $json.periodEnd, performance: ranked, recommendations, totals, recordCount: records.length, optimizedAt: new Date().toISOString() } }];
